public class BellNumbers {

    /**
     * Calculate the Bell number for a given n.
     * 
     * @param n the number of elements in the set
     * @return the Bell number for the given n
     */
    public static long bellNumber(int n) {
        long[] bell = new long[n + 1];
        bell[0] = 1;

        // Fill entries so that they sum up to bell(i)
        for (int i = 1; i <= n; i++) {
            // Fill so that they sum up to bell(i)
            bell[i] = 0;
            for (int j = 0; j < i; j++) {
                bell[i] += bell[j] * combination(i - 1, j);
            }
        }

        return bell[n];
    }

    /**
     * Calculate the binomial coefficient (n choose k).
     * 
     * @param n the total number of items
     * @param k the number of items to choose
     * @return the binomial coefficient
     */
    public static long combination(int n, int k) {
        if (k > n - k) {
            k = n - k;
        }

        long result = 1;
        for (int i = 0; i < k; i++) {
            result = result * (n - i) / (i + 1);
        }

        return result;
    }

    public static void main(String[] args) {
        int n = 4;
        System.out.println("Bell number for " + n + ": " + bellNumber(n));
    }
}
